tool_input.command:
set -e
tmp=$(mktemp -d)
cd "$tmp"
git init -q
git config user.email "a@b.com"; git config user.name "test"
mkdir -p src
cat > src/old.ts <<'EOF'
export function foo() {
  return 1;
}
EOF
git add -A && git commit -q -m init
git mv src/old.ts src/new.ts
cat >> src/new.ts <<'EOF'
export function bar() {
  return 2;
}
export function baz() {
  return 3;
}
EOF
echo "--- name-status ---"
git diff --no-color -M --name-status HEAD
echo "--- numstat ---"
git diff --no-color -M --numstat HEAD
echo "--- numstat -z (hex) ---"
git diff --no-color -M -z --numstat HEAD | xxd | head -20
